css:
@import url("s://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&display=swap");

.scene {
  position: relative;
  width: 240px;
  height: 240px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: "DM Mono", monospace;
  cursor: pointer;
}

.share-toggle {
  display: none;
}

.share-btn {
  position: relative;
  width: 52px;
  height: 52px;
  border-radius: 16px;
  background: #1a1a1f;
  border: 1px solid rgba(255, 255, 255, 0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
  z-index: 10;
}

.share-btn svg {
  fill: rgba(255, 255, 255, 0.5);
  transition: all 0.3s ease;
}

.share-toggle:checked ~ .share-btn {
  background: #22222a;
  border-color: rgba(120, 90, 255, 0.4);
  box-shadow:
    0 0 0 4px rgba(120, 90, 255, 0.1),
    0 8px 32px rgba(0, 0, 0, 0.4);
  transform: scale(1.05);
}

.share-toggle:checked ~ .share-btn svg {
  fill: rgba(255, 255, 255, 0.9);
  filter: drop-shadow(0 0 6px rgba(120, 90, 255, 0.6));
}

.share-btn::before {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: 17px;
  border: 1px solid rgba(120, 90, 255, 0);
  transition: all 0.4s ease;
  pointer-events: none;
}

.share-toggle:checked ~ .share-btn::before {
  border-color: rgba(120, 90, 255, 0.3);
  inset: -6px;
  border-radius: 22px;
}

.icon-close {
  display: none;
}
.share-toggle:checked ~ .share-btn .icon-share {
  display: none;
}
.share-toggle:checked ~ .share-btn .icon-close {
  display: block;
  fill: rgba(255, 255, 255, 0.6);
}

.orbit-ring {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.social-node {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 42px;
  height: 42px;
  border-radius: 13px;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.3);
  transition:
    opacity 0.35s ease,
    transform 0.45s cubic-bezier(0.34, 1.56, 0.64, 1),
    background 0.2s ease,
    box-shadow 0.2s ease;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.share-toggle:checked ~ .orbit-ring {
  pointer-events: all;
}
.share-toggle:checked ~ .orbit-ring .social-node {
  opacity: 1;
}

.n1 {
  --tx: 0px;
  --ty: -88px;
}
.n2 {
  --tx: 62px;
  --ty: -62px;
}
.n3 {
  --tx: 88px;
  --ty: 0px;
}
.n4 {
  --tx: 62px;
  --ty: 62px;
}
.n5 {
  --tx: 0px;
  --ty: 88px;
}
.n6 {
  --tx: -62px;
  --ty: 62px;
}
.n7 {
  --tx: -88px;
  --ty: 0px;
}
.n8 {
  --tx: -62px;
  --ty: -62px;
}

.share-toggle:checked ~ .orbit-ring .n1 {
  transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1);
  transition-delay: 0ms;
}
.share-toggle:checked ~ .orbit-ring .n2 {
  transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1);
  transition-delay: 30ms;
}
.share-toggle:checked ~ .orbit-ring .n3 {
  transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1);
  transition-delay: 55ms;
}
.share-toggle:checked ~ .orbit-ring .n4 {
  transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1);
  transition-delay: 80ms;
}
.share-toggle:checked ~ .orbit-ring .n5 {
  transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1);
  transition-delay: 100ms;
}
.share-toggle:checked ~ .orbit-ring .n6 {
  transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1);
  transition-delay: 80ms;
}
.share-toggle:checked ~ .orbit-ring .n7 {
  transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1);
  transition-delay: 55ms;
}
.share-toggle:checked ~ .orbit-ring .n8 {
  transform: translate(calc(-50% + var(--tx)), calc(-50% + var(--ty))) scale(1);
  transition-delay: 30ms;
}

.n1 {
  background: rgba(120, 90, 255, 0.12);
}
.n1 svg {
  fill: #a07aff;
}
.n1:hover {
  background: #7c5cbf;
  box-shadow: 0 4px 20px rgba(120, 90, 255, 0.45);
}
.n1:hover svg {
  fill: #fff;
}

.n2 {
  background: rgba(4, 98, 223, 0.12);
}
.n2 svg {
  fill: #4f8ef7;
}
.n2:hover {
  background: #0462df;
  box-shadow: 0 4px 20px rgba(4, 98, 223, 0.4);
}
.n2:hover svg {
  fill: #fff;
}

.n3 {
  background: rgba(37, 211, 102, 0.12);
}
.n3 svg {
  fill: #25d366;
}
.n3:hover {
  background: #25d366;
  box-shadow: 0 4px 20px rgba(37, 211, 102, 0.4);
}
.n3:hover svg {
  fill: #fff;
}

.n4 {
  background: rgba(88, 101, 242, 0.12);
}
.n4 svg {
  fill: #8c9eff;
}
.n4:hover {
  background: #5865f2;
  box-shadow: 0 4px 20px rgba(88, 101, 242, 0.4);
}
.n4:hover svg {
  fill: #fff;
}

.n5 {
  background: rgba(255, 69, 0, 0.12);
}
.n5 svg {
  fill: #ff6534;
}
.n5:hover {
  background: #ff4500;
  box-shadow: 0 4px 20px rgba(255, 69, 0, 0.4);
}
.n5:hover svg {
  fill: #fff;
}

.n6 {
  background: rgba(225, 48, 108, 0.12);
}
.n6 svg {
  fill: #e1306c;
}
.n6:hover {
  background: linear-gradient(
    135deg,
    #f09433,
    #e6683c,
    #dc2743,
    #cc2366,
    #bc1888
  );
  box-shadow: 0 4px 20px rgba(225, 48, 108, 0.4);
}
.n6:hover svg {
  fill: #fff;
}

.n7 {
  background: rgba(255, 252, 0, 0.08);
}
.n7 svg {
  fill: #fffc00;
}
.n7:hover {
  background: #fffc00;
  box-shadow: 0 4px 20px rgba(255, 252, 0, 0.35);
}
.n7:hover svg {
  fill: #000;
}

.n8 {
  background: rgba(189, 8, 28, 0.12);
}
.n8 svg {
  fill: #e60023;
}
.n8:hover {
  background: #e60023;
  box-shadow: 0 4px 20px rgba(189, 8, 28, 0.4);
}
.n8:hover svg {
  fill: #fff;
}

.social-node::after {
  content: attr(data-label);
  position: absolute;
  bottom: -22px;
  left: 50%;
  transform: translateX(-50%);
  font-size: 9px;
  letter-spacing: 0.05em;
  color: rgba(255, 255, 255, 0.28);
  white-space: nowrap;
  opacity: 0;
  transition: opacity 0.15s ease;
  pointer-events: none;
}
.social-node:hover::after {
  opacity: 1;
  color: rgba(255, 255, 255, 0.65);
}
